"use client";
/**
 * v188 · «Ranking Juegos» (v189: for the chosen period — 1W, 1M, 6M, 1Y, all): income generated by each game. A game's income is its share of the month's net commission
 * on changing euros ↔ cosmicoins, by its counted matches (lib/studioPayout.ts). Until that ledger exists the tab shows
 * sample data and says so («datos de ejemplo»). One series per chart (one hue, no legend): the month total over six
 * months, and each game's bar; tapping a game opens its own six-month line. Values are text, never colour alone, and
 * every chart has a table for screen readers. v223 (owner): no «datos de ejemplo» badge and no period subtitle; the
 * series is still sample data until the commission ledger exists (docs/STATE.md).
 */
import { useId, useMemo, useState } from "react";
import { GAMES, playableForMoney } from "@/lib/games";
import { COIN_SYMBOL, formatNumber, getLocale, t, useI18n } from "@/lib/i18n";
import { localeInfo } from "@/lib/i18n/locales";
import { gameName } from "@/lib/i18n/games";
import { sampleIncomeSeries } from "@/lib/demo/sampleGameIncome";
import type { RankingPeriod } from "@/lib/rankingPeriod";
import st from "./GamesIncomeRanking.module.css";

const euros = (cents: number, decimals = 0) =>
  `${formatNumber(cents / 100, { minimumFractionDigits: decimals, maximumFractionDigits: decimals })} ${COIN_SYMBOL}`;

function LineChart({ values, labels, name }: { values: number[]; labels: string[]; name: string }) {
  const [pickRaw, setPick] = useState(values.length - 1);
  const fillId = `gi-fill-${useId().replace(/:/g, "")}`;
  const pick = Math.min(pickRaw, values.length - 1);
  const w = 300, h = 108, padTop = 38, padBottom = 6;
  const max = Math.max(...values, 1) * 1.08;
  const x = (i: number) => (values.length === 1 ? w / 2 : 12 + (i * (w - 24)) / (values.length - 1));
  const y = (v: number) => padTop + (1 - v / max) * (h - padTop - padBottom);
  const points = values.map((v, i) => `${x(i)},${y(v)}`).join(" ");
  const tipX = Math.min(w - 58, Math.max(58, x(pick)));
  // At most six labels under the axis (always the first and the last); the picked point names its date above it.
  const step = Math.max(1, Math.ceil((values.length - 1) / 5));
  const last = values.length - 1;
  const shown = new Set(values.map((_, i) => i).filter((i) => i === last || (i % step === 0 && last - i >= step * 0.7)));
  return (
    <figure className={st.chart}>
      <svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label={t("ranking.gamesChartAria", { name })}>
        {/* v192: no grid and no baseline (owner); a soft fill under a fine line carries the shape. */}
        <defs>
          <linearGradient id={fillId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#9fe6ff" stopOpacity=".22" />
            <stop offset="100%" stopColor="#9fe6ff" stopOpacity="0" />
          </linearGradient>
        </defs>
        <polygon points={`${x(0)},${h - padBottom} ${points} ${x(values.length - 1)},${h - padBottom}`} fill={`url(#${fillId})`} />
        <polyline points={points} className={st.line} />
        {values.map((v, i) => (i === pick || values.length <= 12) && <circle key={i} cx={x(i)} cy={y(v)} r={i === pick ? 4.5 : 3} className={i === pick ? st.dotOn : st.dot} />)}
        {/* v223 (owner): the amount on top, its date underneath. */}
        <text x={tipX} y={Math.max(14, y(values[pick]) - 23)} textAnchor="middle" className={st.tip}>{euros(values[pick])}</text>
        <text x={tipX} y={Math.max(28, y(values[pick]) - 10)} textAnchor="middle" className={st.tipDate}>{labels[pick]}</text>
        {values.map((_, i) => (
          <rect key={i} x={x(i) - (w - 24) / (2 * Math.max(1, values.length - 1))} y="0" width={(w - 24) / Math.max(1, values.length - 1)} height={h}
            className={st.hit} onPointerEnter={() => setPick(i)} onClick={() => setPick(i)} />
        ))}
      </svg>
      <div className={st.axis} aria-hidden="true">
        {labels.map((l, i) => shown.has(i) && (
          <span key={i} data-on={i === pick || undefined} style={{ left: `${(x(i) / w) * 100}%` }}>{l}</span>
        ))}
      </div>
      <table className="visuallyHidden">
        <caption>{t("ranking.gamesChartAria", { name })}</caption>
        <tbody>{labels.map((l, i) => <tr key={i}><th scope="row">{l}</th><td>{euros(values[i], 2)}</td></tr>)}</tbody>
      </table>
    </figure>
  );
}

export default function GamesIncomeRanking({ period }: { period: RankingPeriod }) {
  useI18n();
  const locale = getLocale();
  // v189: games of chance are never played for money, so they generate no income and are not listed.
  const moneyGames = useMemo(() => GAMES.filter(playableForMoney), []);
  const series = useMemo(() => sampleIncomeSeries(moneyGames.map((g) => g.id), period, new Date()), [period, moneyGames]);
  const labels = useMemo(() => {
    const intl = localeInfo(locale).intl;
    const f = series.granularity === "day"
      ? new Intl.DateTimeFormat(intl, { day: "numeric", month: "short", timeZone: "UTC" })
      : new Intl.DateTimeFormat(intl, period === "all" || period === "1y" ? { month: "short", year: "2-digit", timeZone: "UTC" } : { month: "short", timeZone: "UTC" });
    return series.points.map((m) => f.format(m).replace(".", ""));
  }, [series, locale, period]);
  const rows = useMemo(
    () => moneyGames.map((g) => {
      const values = series.perGame[g.id];
      return { game: g, series: values, now: values.reduce((a, b) => a + b, 0) };
    }).sort((a, b) => b.now - a.now),
    [series, moneyGames],
  );
  const totals = series.points.map((_, i) => rows.reduce((sum, r) => sum + r.series[i], 0));
  const periodTotal = totals.reduce((a, b) => a + b, 0);
  const top = rows[0]?.now ?? 1;
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className={st.wrap}>
      <section className={st.card} aria-labelledby="gi-total">
        <div className={st.cardHead}>
          <span id="gi-total">{t("ranking.gamesPeriodTotal")}</span>
          <strong dir="ltr">{euros(periodTotal)}</strong>
        </div>
        <LineChart values={totals} labels={labels} name={t("ranking.gamesAll")} />
      </section>
      <section aria-labelledby="gi-list">
        <h2 id="gi-list" className={st.listTitle}>{t("ranking.gamesByGame")}</h2>
        <ol className={st.list}>
          {rows.map((r, i) => {
            const isOpen = open === r.game.id;
            return (
              <li key={r.game.id} className={st.row} data-open={isOpen || undefined}>
                <button type="button" className={st.rowButton} aria-expanded={isOpen} onClick={() => setOpen(isOpen ? null : r.game.id)}>
                  <span className={st.pos}>{i + 1}</span>
                  <img src={r.game.cover} alt="" width={36} height={36} loading="lazy" />
                  <span className={st.name}>{gameName(r.game)}</span>
                  <b className={st.value} dir="ltr">{euros(r.now)}</b>
                  <span className={st.bar} aria-hidden="true"><i style={{ width: `${Math.max(2, (r.now / top) * 100)}%` }} /></span>
                </button>
                {isOpen && (
                  <div className={st.detail}>
                    <small className={st.sub}>{t("ranking.gamesEvolution", { game: gameName(r.game) })}</small>
                    <LineChart values={r.series} labels={labels} name={gameName(r.game)} />
                  </div>
                )}
              </li>
            );
          })}
        </ol>
      </section>
      <p className="rankingNote">{t("ranking.gamesNote")}</p>
    </div>
  );
}
